WITH base AS (SELECT *, CONCAT_WS('-', firmware, device_code) AS firmware_device_code_key FROM device_readings WHERE status_bits <> 4), flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) > INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM base), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged), metrics AS (SELECT id, temp_c, firmware, LEAD(humidity) OVER (PARTITION BY device_code ORDER BY temp_c ASC, id ASC) AS next_humidity, LAG(burst_id) OVER (PARTITION BY device_code ORDER BY temp_c ASC, id ASC) AS prev_burst_id, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY temp_c ASC, id ASC) AS row_seq, LEAD(temp_c, 2) OVER (ORDER BY reading_ts ASC, id ASC) AS next_temp_c FROM islands), valid AS (SELECT *, FLOOR(temp_c) AS temp_c_whole, CAST(next_humidity AS INT) AS next_humidity_int FROM metrics WHERE firmware = '1.0.3') SELECT *, RANK() OVER (ORDER BY next_temp_c DESC NULLS FIRST) AS next_temp_c_rank, ROW_NUMBER() OVER (ORDER BY row_seq ASC, id ASC) AS row_seq_2, FIRST_VALUE(temp_c, TRUE) OVER (ORDER BY next_humidity ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_temp_c, SUM(prev_burst_id) OVER w_part AS cumulative_prev_burst_id FROM valid WHERE temp_c_whole > 72 WINDOW w_part AS (ORDER BY prev_burst_id ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
